//! Declares every app command to Tauri's ACL.
//!
//! `AppManifest::commands` writes `permissions/autogenerated/<cmd>.toml` into
//! the crate source and re-reads it on every build, so that directory is
//! committed. Once the manifest exists the ACL gates *every* command: a name
//! missing from this list — or from `capabilities/main.json`'s `allow-*`
//! entries — is refused in JS with the bare string
//! `"<cmd> not allowed. Command not found"`.
fn main() {
    const COMMANDS: &[&str] = &[
        "health",
        "market_snapshot",
        "trades",
        "trades_closed",
        "portfolio",
        "risk_graph",
        "what_if",
        "reconciliation",
        "warnings",
        "app_config",
        "reload",
        "trade_source",
        "probe_trade_source",
        "set_trade_source",
        "clear_trade_source",
        "pick_csv_file",
        // The Model tab: two chain reads and the extra quote universe.
        "chain_expirations",
        "option_chain",
        "set_model_contracts",
        // Settings, diagnostics, the demo book and the openers.
        "load_demo",
        "leave_demo",
        "diagnostics",
        "settings_read",
        "settings_update",
        "pick_python",
        "pick_env_file",
        "pick_token_file",
        "pick_tastytrade_env_file",
        "probe_python",
        "reveal_folder",
        "open_log_folder",
        "open_config_file",
        "open_sheet",
        "check_for_updates",
    ];
    let attrs = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS));
    tauri_build::try_build(attrs).expect("tauri_build with the app manifest");
}
